{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE FUNCTION RUBYSORGANICS_DB.MAPLEMONK.SOLVE_BOGO_SUBSET_SUM_JS( ITEM_MRPS_JSON STRING, TARGET_DISCOUNT FLOAT ) RETURNS STRING LANGUAGE JAVASCRIPT STRICT AS $$ if (TARGET_DISCOUNT === null || TARGET_DISCOUNT === undefined || !ITEM_MRPS_JSON) { return JSON.stringify([]); } var target = Math.abs(Number(TARGET_DISCOUNT)); if (!isFinite(target) || target <= 0) { return JSON.stringify([]); } var items; try { items = JSON.parse(ITEM_MRPS_JSON); } catch (e) { return JSON.stringify([]); } if (!Array.isArray(items) || items.length === 0) { return JSON.stringify([]); } var expanded = []; for (var i = 0; i < items.length; i++) { var it = items[i]; if (!it || it.line_id === null || it.line_id === undefined) { continue; } var mrp = Number(it.mrp); if (!isFinite(mrp) || mrp <= 0) { continue; } var rawQty = Number(it.qty); var q = (isFinite(rawQty) && Math.abs(rawQty) > 0) ? Math.min(Math.abs(Math.round(rawQty)), 20) : 1; var rawSales = Number(it.unit_sales); var salesPaise = (isFinite(rawSales) && rawSales >= 0) ? Math.round(rawSales * 100) : 100000000000; var rawPaid = Number(it.unit_paid); var paidPaise = (isFinite(rawPaid) && rawPaid >= 0) ? Math.round(rawPaid * 100) : salesPaise; var rawCogs = Number(it.bogo_cogs); var cogsPaise = (isFinite(rawCogs) && rawCogs > 0) ? Math.round(rawCogs * 100) : 0; var mrpPaise = Math.round(mrp * 100); var lineId = String(it.line_id); for (var k = 0; k < q; k++) { expanded.push({ line_id: lineId, mrpPaise: mrpPaise, salesPaise: salesPaise, cogsPaise: cogsPaise, paidPaise: paidPaise }); } } if (expanded.length === 0) { return JSON.stringify([]); } // Deterministic order: lowest TOTAL_SALES -> lowest COGS -> lowest PAID -> lowest MRP expanded.sort(function(a, b) { if (a.salesPaise !== b.salesPaise) { return a.salesPaise - b.salesPaise; } if (a.cogsPaise !== b.cogsPaise) { return a.cogsPaise - b.cogsPaise; } if (a.paidPaise !== b.paidPaise) { return a.paidPaise - b.paidPaise; } return a.mrpPaise - b.mrpPaise; }); function isBetterTieBreak(cand, curr) { if (cand.salesPaise !== curr.salesPaise) { return cand.salesPaise < curr.salesPaise; } if (cand.cogsPaise !== curr.cogsPaise) { return cand.cogsPaise < curr.cogsPaise; } if (cand.paidPaise !== curr.paidPaise) { return cand.paidPaise < curr.paidPaise; } return cand.count > curr.count; } var targetPaise = Math.round(target * 100); var tolerancePaise = Math.round(Math.max(5.0, 0.02 * target) * 100); var maxAllowedSumPaise = targetPaise + tolerancePaise + 100; // Subset-Sum DP: key = MRP sum in paise -> best candidate state var dp = new Map(); dp.set(0, { sumPaise: 0, salesPaise: 0, cogsPaise: 0, paidPaise: 0, count: 0, combo: [] }); var MAX_STATES = 5000; for (var idx = 0; idx < expanded.length; idx++) { var unit = expanded[idx]; var snapshot = []; dp.forEach(function(val) { snapshot.push(val); }); for (var s = 0; s < snapshot.length; s++) { var st = snapshot[s]; var newSumPaise = st.sumPaise + unit.mrpPaise; if (newSumPaise > maxAllowedSumPaise) { continue; } var cand = { sumPaise: newSumPaise, salesPaise: st.salesPaise + unit.salesPaise, cogsPaise: st.cogsPaise + unit.cogsPaise, paidPaise: st.paidPaise + unit.paidPaise, count: st.count + 1, combo: st.combo.concat([unit.line_id]) }; var existing = dp.get(newSumPaise); if (!existing) { if (dp.size >= MAX_STATES) { continue; } dp.set(newSumPaise, cand); } else if (isBetterTieBreak(cand, existing)) { dp.set(newSumPaise, cand); } } } // Tier 1: Closest MRP match within tolerance (tie-break: lowest TOTAL_SALES -> lowest COGS) var bestMatch = null; var bestDiffPaise = Infinity; // Tier 2: Stacked-discount fallback (highest MRP sum <= target + 1, same tie-break) var bestUnder = null; dp.forEach(function(st, sumPaise) { if (sumPaise === 0 || st.count === 0) { return; } var diffPaise = Math.abs(sumPaise - targetPaise); if (diffPaise <= tolerancePaise) { if ( !bestMatch || diffPaise < bestDiffPaise || (diffPaise === bestDiffPaise && isBetterTieBreak(st, bestMatch)) ) { bestMatch = st; bestDiffPaise = diffPaise; } } if (sumPaise <= targetPaise + 100) { if ( !bestUnder || sumPaise > bestUnder.sumPaise || (sumPaise === bestUnder.sumPaise && isBetterTieBreak(st, bestUnder)) ) { bestUnder = st; } } }); if (bestMatch) { return JSON.stringify(bestMatch.combo); } if (bestUnder) { return JSON.stringify(bestUnder.combo); } return JSON.stringify([]); $$; CREATE OR REPLACE VIEW RUBYSORGANICS_DB.MAPLEMONK.VW_SHOPIFY_PARSED_DISCOUNT_CODES AS WITH order_base AS ( SELECT ORDER_NAME, MAX(DISCOUNT_CODE) AS DISCOUNT_CODE, MAX(TAGS) AS TAGS FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS GROUP BY ORDER_NAME ), parsed_discount_applications AS ( SELECT ORDER_NAME, ARRAY_AGG( DISTINCT UPPER( TRIM( COALESCE( NULLIF(TRIM(f.value:code::STRING), \'\'), NULLIF(TRIM(f.value:title::STRING), \'\') ) ) ) ) AS APP_CODES FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS, LATERAL FLATTEN(INPUT => DISCOUNT_APPLICATIONS) f WHERE COALESCE(LOWER(f.value:target_type::STRING), \'line_item\') <> \'shipping_line\' AND COALESCE(NULLIF(TRIM(f.value:code::STRING), \'\'), NULLIF(TRIM(f.value:title::STRING), \'\')) IS NOT NULL GROUP BY ORDER_NAME ), parsed_note_attributes AS ( SELECT ORDER_NAME, ARRAY_AGG(DISTINCT UPPER(TRIM(SPLIT_PART(f.value:name::STRING, \'|\', 2)))) AS ATTR_CODES FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS, LATERAL FLATTEN(INPUT => NOTE_ATTRIBUTES) f WHERE LOWER(TRIM(f.value:name::STRING)) LIKE \'discount |%\' AND TRIM(SPLIT_PART(f.value:name::STRING, \'|\', 2)) <> \'\' GROUP BY ORDER_NAME ), parsed_tags AS ( SELECT ORDER_NAME, ARRAY_AGG(DISTINCT UPPER(TRIM(t.value::STRING))) AS TAG_CODES FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS, LATERAL FLATTEN(INPUT => SPLIT(TAGS, \',\')) t WHERE UPPER(TRIM(t.value::STRING)) IN ( \'BUNDLE3\', \'BUNDLE4\', \'HELLORUBY\', \'LIPDAYBOGO\', \'FIRST999\', \'RUBY999\', \'RUBYFLASH\', \'HELLOHYDRA\', \'MISSEDYA25\', \'MYSTERYGIFT\', \'VIP15\', \'EMPLOYEEDISCOUNT50\', \'FREEGIFT\', \'FREEMINIPUFF\', \'FREE MINI PUFF\', \'FREE PUFF (CONCEALER OFFER)\', \'FREE PUFF (COMPACT OFFER)\', \'FREE PUFF (FOUNDATION OFFER)\', \'BOGO\', \'MONSOON SALE: BOGO!\', \'MONSOON SALE: BOGO\', \'MONSOON SALE: BUY 1 GET 1 FREE\', \'FESTIVE SALE: BOGO\', \'FESTIVE SALE: BUY 1 GET 1 FREE\', \'PAYDAY SALE: BUY 1 GET 1 FREE\', \'SUMMER SALE - BUY 1 GET 1 FREE!\' ) OR UPPER(TRIM(t.value::STRING)) LIKE \'%BOGO%\' OR UPPER(TRIM(t.value::STRING)) LIKE \'%BUY 1 GET 1%\' GROUP BY ORDER_NAME ) SELECT b.ORDER_NAME, COALESCE( NULLIF( TRIM( ARRAY_TO_STRING( ARRAY_DISTINCT( ARRAY_CAT( COALESCE(na.ATTR_CODES, ARRAY_CONSTRUCT()), ARRAY_CAT( COALESCE(da.APP_CODES, ARRAY_CONSTRUCT()), ARRAY_CAT( CASE WHEN TRIM(COALESCE(b.DISCOUNT_CODE, \'\')) <> \'\' THEN ARRAY_CONSTRUCT(UPPER(TRIM(b.DISCOUNT_CODE))) ELSE ARRAY_CONSTRUCT() END, COALESCE(pt.TAG_CODES, ARRAY_CONSTRUCT()) ) ) ) ), \' + \' ) ), \'\' ), \'No discount\' ) AS ALL_DISCOUNT_CODES_APPLIED FROM order_base b LEFT JOIN parsed_discount_applications da ON b.ORDER_NAME = da.ORDER_NAME LEFT JOIN parsed_note_attributes na ON b.ORDER_NAME = na.ORDER_NAME LEFT JOIN parsed_tags pt ON b.ORDER_NAME = pt.ORDER_NAME; CREATE OR REPLACE TRANSIENT TABLE RUBYSORGANICS_DB.MAPLEMONK.TEMP_LINE_ITEM_BASE AS WITH mrp_master AS ( SELECT UPPER(TRIM(\"Product Title\")) AS PRODUCT_TITLE_CLEAN, MAX(COALESCE(TRY_TO_DOUBLE(REPLACE(\"MRP\"::STRING, \',\', \'\')), 0)) AS UNIT_MRP, MAX(COALESCE(TRY_TO_DOUBLE(REPLACE(\"FREEBIE COGS\"::STRING, \',\', \'\')), 0)) AS UNIT_FREEBIE_COGS, MAX(COALESCE(TRY_TO_DOUBLE(REPLACE(\"FREEBIE BOGO\"::STRING, \',\', \'\')), 0)) AS UNIT_FREEBIE_BOGO FROM RUBYSORGANICS_DB.MAPLEMONK.gs_mrp_cogs_sheet1 WHERE TRIM(COALESCE(\"Product Title\", \'\')) <> \'\' GROUP BY UPPER(TRIM(\"Product Title\")) ), line_base AS ( SELECT s.ORDER_NAME, s.ORDER_TIMESTAMP::DATE AS ORDER_DATE, s.LINE_ITEM_ID::STRING AS LINE_ITEM_ID, TRIM(SPLIT_PART(s.PRODUCT_NAME, \' - \', 1)) AS BASE_PRODUCT_NAME, s.CATEGORY, CASE WHEN s.IS_REFUND = 1 OR LOWER(s.ORDER_STATUS) = \'cancelled\' THEN -1 * ABS(COALESCE(NULLIF(s.REFUND_QUANTITY, 0), s.QUANTITY, 1)) WHEN COALESCE(s.QUANTITY, 0) = 0 THEN -1 * ABS(COALESCE(s.REFUND_QUANTITY, 1)) ELSE s.QUANTITY END AS EFFECTIVE_QTY, CASE WHEN s.IS_REFUND = 1 OR LOWER(s.ORDER_STATUS) = \'cancelled\' THEN -1 * ABS(COALESCE(s.GROSS_SALES_AFTER_TAX, s.TOTAL_SALES, 0) - COALESCE(s.DISCOUNT, 0)) ELSE COALESCE(s.GROSS_SALES_AFTER_TAX, s.TOTAL_SALES, 0) - COALESCE(s.DISCOUNT, 0) END AS PAID_SELLING_PRICE, s.GROSS_SALES_BEFORE_TAX, s.GROSS_SALES_AFTER_TAX, s.TOTAL_SALES, s.QUANTITY, s.DISCOUNT, s.DISCOUNT_BEFORE_TAX, s.TAX, s.IS_REFUND, s.REFUND_QUANTITY, dc.ALL_DISCOUNT_CODES_APPLIED FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS s LEFT JOIN RUBYSORGANICS_DB.MAPLEMONK.VW_SHOPIFY_PARSED_DISCOUNT_CODES dc ON s.ORDER_NAME = dc.ORDER_NAME ) SELECT l.*, COALESCE(m.UNIT_MRP, 0) AS UNIT_MRP, COALESCE(m.UNIT_FREEBIE_COGS, 0) AS UNIT_FREEBIE_COGS, COALESCE(m.UNIT_FREEBIE_BOGO, 0) AS UNIT_FREEBIE_BOGO, CASE WHEN ( UPPER(l.ALL_DISCOUNT_CODES_APPLIED) LIKE \'%BOGO%\' OR UPPER(l.ALL_DISCOUNT_CODES_APPLIED) LIKE \'%BUY 1 GET 1%\' ) AND ABS(l.PAID_SELLING_PRICE) <= 0.01 AND COALESCE(l.TAX, 0) = 0 AND ABS(COALESCE(l.DISCOUNT, 0)) > 0 AND COALESCE(m.UNIT_FREEBIE_BOGO, 0) > 0 AND COALESCE(m.UNIT_MRP, 0) > 0 AND ABS( ABS(l.DISCOUNT) - (ROUND(ABS(l.DISCOUNT) / m.UNIT_MRP) * m.UNIT_MRP) ) <= GREATEST(2.0, 0.002 * ABS(l.DISCOUNT)) THEN LEAST( ABS(l.EFFECTIVE_QTY), GREATEST(1, ROUND(ABS(l.DISCOUNT) / m.UNIT_MRP)) ) ELSE 0 END AS EXPLICIT_FREE_BOGO_QTY FROM line_base l LEFT JOIN mrp_master m ON UPPER(TRIM(l.BASE_PRODUCT_NAME)) = m.PRODUCT_TITLE_CLEAN; CREATE OR REPLACE TRANSIENT TABLE RUBYSORGANICS_DB.MAPLEMONK.TEMP_SOLVED_BOGO_LINES AS WITH order_note_attrs AS ( SELECT ORDER_NAME, NOTE_ATTRIBUTES FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS QUALIFY ROW_NUMBER() OVER (PARTITION BY ORDER_NAME ORDER BY LINE_ITEM_ID) = 1 ), note_attr_bogo_discount AS ( SELECT o.ORDER_NAME, SUM(COALESCE(TRY_TO_DOUBLE(f.value:value::STRING), 0)) AS ATTR_BOGO_DISCOUNT FROM order_note_attrs o, LATERAL FLATTEN(INPUT => o.NOTE_ATTRIBUTES) f WHERE LOWER(TRIM(f.value:name::STRING)) LIKE \'discount |%\' AND ( UPPER(SPLIT_PART(f.value:name::STRING, \'|\', 2)) LIKE \'%BOGO%\' OR UPPER(SPLIT_PART(f.value:name::STRING, \'|\', 2)) LIKE \'%BUY 1 GET 1%\' ) GROUP BY o.ORDER_NAME ), order_totals AS ( SELECT ORDER_NAME, ABS(SUM(COALESCE(NULLIF(DISCOUNT, 0), DISCOUNT_BEFORE_TAX * 1.18, 0))) AS FULL_ORDER_DISCOUNT FROM RUBYSORGANICS_DB.MAPLEMONK.TEMP_LINE_ITEM_BASE WHERE UPPER(ALL_DISCOUNT_CODES_APPLIED) LIKE \'%BOGO%\' OR UPPER(ALL_DISCOUNT_CODES_APPLIED) LIKE \'%BUY 1 GET 1%\' GROUP BY ORDER_NAME HAVING SUM(EXPLICIT_FREE_BOGO_QTY) = 0 ), orders_needing_solve AS ( SELECT b.ORDER_NAME, COALESCE(NULLIF(na.ATTR_BOGO_DISCOUNT, 0), ot.FULL_ORDER_DISCOUNT) AS BOGO_TARGET_DISCOUNT, ARRAY_AGG( OBJECT_CONSTRUCT( \'line_id\', b.LINE_ITEM_ID, \'mrp\', b.UNIT_MRP, \'bogo_cogs\', b.UNIT_FREEBIE_BOGO, \'unit_sales\', ROUND(ABS(COALESCE(b.TOTAL_SALES, b.PAID_SELLING_PRICE, 0)) / NULLIF(ABS(b.EFFECTIVE_QTY), 0), 2), \'unit_paid\', ROUND(ABS(COALESCE(b.PAID_SELLING_PRICE, 0)) / NULLIF(ABS(b.EFFECTIVE_QTY), 0), 2), \'qty\', ABS(b.EFFECTIVE_QTY) ) ) WITHIN GROUP ( ORDER BY ROUND(ABS(COALESCE(b.TOTAL_SALES, b.PAID_SELLING_PRICE, 0)) / NULLIF(ABS(b.EFFECTIVE_QTY), 0), 2) ASC, b.UNIT_FREEBIE_BOGO ASC, ROUND(ABS(COALESCE(b.PAID_SELLING_PRICE, 0)) / NULLIF(ABS(b.EFFECTIVE_QTY), 0), 2) ASC, b.LINE_ITEM_ID ASC ) AS ITEMS_JSON FROM RUBYSORGANICS_DB.MAPLEMONK.TEMP_LINE_ITEM_BASE b INNER JOIN order_totals ot ON b.ORDER_NAME = ot.ORDER_NAME LEFT JOIN note_attr_bogo_discount na ON b.ORDER_NAME = na.ORDER_NAME WHERE b.UNIT_FREEBIE_BOGO > 0 AND b.UNIT_MRP > 0 AND ABS(b.EFFECTIVE_QTY) > 0 GROUP BY b.ORDER_NAME, COALESCE(NULLIF(na.ATTR_BOGO_DISCOUNT, 0), ot.FULL_ORDER_DISCOUNT) ), udf_execution AS ( SELECT ORDER_NAME, PARSE_JSON( RUBYSORGANICS_DB.MAPLEMONK.SOLVE_BOGO_SUBSET_SUM_JS( ITEMS_JSON::STRING, BOGO_TARGET_DISCOUNT::FLOAT ) ) AS SOLVED_LINE_IDS_ARRAY FROM orders_needing_solve WHERE BOGO_TARGET_DISCOUNT > 0 ), flattened_lines AS ( SELECT u.ORDER_NAME, f.value::STRING AS FREE_LINE_ITEM_ID FROM udf_execution u, LATERAL FLATTEN(INPUT => u.SOLVED_LINE_IDS_ARRAY) f ) SELECT ORDER_NAME, FREE_LINE_ITEM_ID, COUNT(*) AS SOLVED_FREE_BOGO_QTY FROM flattened_lines GROUP BY ORDER_NAME, FREE_LINE_ITEM_ID; CREATE OR REPLACE TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_LINE_ITEM_DISCOUNTING_FACT AS SELECT b.ORDER_NAME, b.ORDER_DATE, b.LINE_ITEM_ID, b.BASE_PRODUCT_NAME, b.UNIT_MRP, b.UNIT_FREEBIE_COGS, b.UNIT_FREEBIE_BOGO, b.EFFECTIVE_QTY AS QTY, CASE WHEN b.IS_REFUND = 1 OR b.EFFECTIVE_QTY < 0 THEN b.EFFECTIVE_QTY ELSE 0 END AS REVERSED_QTY, b.PAID_SELLING_PRICE, LEAST( ABS(b.EFFECTIVE_QTY), CASE WHEN b.EXPLICIT_FREE_BOGO_QTY > 0 THEN b.EXPLICIT_FREE_BOGO_QTY WHEN s.SOLVED_FREE_BOGO_QTY IS NOT NULL THEN s.SOLVED_FREE_BOGO_QTY ELSE 0 END ) AS FREE_BOGO_QTY, (b.EFFECTIVE_QTY - (SIGN(b.EFFECTIVE_QTY) * FREE_BOGO_QTY)) AS PAID_QTY, (FREE_BOGO_QTY * b.UNIT_FREEBIE_BOGO * SIGN(b.EFFECTIVE_QTY)) AS FREEBIE_BOGO_VALUE, (b.EFFECTIVE_QTY * b.UNIT_FREEBIE_COGS) AS FREEBIE_GWP_VALUE, ((b.EFFECTIVE_QTY - (SIGN(b.EFFECTIVE_QTY) * FREE_BOGO_QTY)) * b.UNIT_MRP) AS ADJUSTED_LINE_MRP_VALUE, b.ALL_DISCOUNT_CODES_APPLIED, b.IS_REFUND, b.REFUND_QUANTITY FROM RUBYSORGANICS_DB.MAPLEMONK.TEMP_LINE_ITEM_BASE b LEFT JOIN RUBYSORGANICS_DB.MAPLEMONK.TEMP_SOLVED_BOGO_LINES s ON b.ORDER_NAME = s.ORDER_NAME AND b.LINE_ITEM_ID = s.FREE_LINE_ITEM_ID; CREATE OR REPLACE TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_ORDER_DISCOUNTING_SUMMARY AS WITH order_aggregates AS ( SELECT ORDER_NAME, MIN(ORDER_DATE) AS ORDER_DATE, MAX(ALL_DISCOUNT_CODES_APPLIED) AS DISCOUNT_CODE, SUM(PAID_SELLING_PRICE) AS PAID_TOTAL, SUM(ADJUSTED_LINE_MRP_VALUE) AS GROSS_MRP, SUM(FREEBIE_GWP_VALUE) AS TOTAL_FREEBIE_GWP, SUM(FREEBIE_BOGO_VALUE) AS TOTAL_FREEBIE_BOGO, SUM(QTY) AS SUM_OF_QUANTITY, SUM(REVERSED_QTY) AS SUM_OF_REVERSED_QUANTITY FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_LINE_ITEM_DISCOUNTING_FACT GROUP BY ORDER_NAME ) SELECT ORDER_NAME, ORDER_DATE, DISCOUNT_CODE, CASE WHEN ABS(PAID_TOTAL) < 0.01 AND (UPPER(DISCOUNT_CODE) LIKE \'%BOGO%\' OR UPPER(DISCOUNT_CODE) LIKE \'%BUY 1 GET 1%\') THEN 1 ELSE 0 END AS ZERO_TOTAL_BOGO_FLAG, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE PAID_TOTAL END AS TOTAL, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE GROSS_MRP END AS MRP, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE (GROSS_MRP - PAID_TOTAL) END AS DISCOUNT, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 OR GROSS_MRP = 0 THEN 0 ELSE (GROSS_MRP - PAID_TOTAL) / NULLIF(GROSS_MRP, 0) END AS DISCOUNT_PCT, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE TOTAL_FREEBIE_GWP END AS FREEBIE_GWP, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE TOTAL_FREEBIE_BOGO END AS FREEBIE_BOGO, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE ((GROSS_MRP - PAID_TOTAL) + TOTAL_FREEBIE_GWP + TOTAL_FREEBIE_BOGO) END AS TOTAL_DISCOUNT_PLUS_FREEBIE, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 OR GROSS_MRP = 0 THEN 0 ELSE ((GROSS_MRP - PAID_TOTAL) + TOTAL_FREEBIE_GWP + TOTAL_FREEBIE_BOGO) / NULLIF(GROSS_MRP, 0) END AS TOTAL_DISCOUNT_PLUS_FREEBIE_PCT, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE SUM_OF_QUANTITY END AS SUM_OF_QUANTITY, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE SUM_OF_REVERSED_QUANTITY END AS SUM_OF_REVERSED_QUANTITY FROM order_aggregates;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from RUBYSORGANICS_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
